        TweenService:Create(stroke, TweenInfo.new(0.16), {Color = Color3.fromRGB(43, 43, 54), Transparency = 0.20}):Play()
        TweenService:Create(input, TweenInfo.new(0.16), {BackgroundColor3 = Color3.fromRGB(18, 18, 23)}):Play()
    end)

    return input
end

